// ── UNIVERSAL JOB LISTING PARSER ──────────────────────────
// Handles: LinkedIn (JSON), Naukri (HTML), Shell, Barclays,
// Deutsche Bank, Cummins, Honeywell, VWITS, Eaton, HSBC,
// BP, Maersk, Mercedes, Goldman, Bosch, Siemens, EY GDS,
// Unilever, Cargill, Telstra, Amex, Nokia, AstraZeneca,
// JPMorgan, Deloitte, Novartis, StanChart, 3M, Fidelity,
// DP World + generic HTML fallback

const upstream = $('Code — Build All GCC Search URLs').item.json;
const board = upstream.board || '';
const label = upstream.label || '';
const company = upstream.company || '';
const sourceUrl = upstream.url || '';
const scrapedAt = upstream.scraped_at || new Date().toISOString();
const raw = $input.first().json;
const html = typeof raw === 'string' ? raw : JSON.stringify(raw);

const jobs = [];

// ── LinkedIn guest API (returns JSON) ─────────────────────
if (board === 'LinkedIn') {
  try {
    const data = typeof raw === 'object' ? raw : JSON.parse(html);
    const elements = data?.included || data?.elements || [];
    elements.slice(0, 15).forEach(el => {
      const title = el?.title || el?.jobPostingTitle || '';
      const co = el?.primaryDescription?.text || el?.companyName || company;
      const location = el?.secondaryDescription?.text || el?.formattedLocation || 'India';
      const jobUrl = el?.jobPostingUrl || sourceUrl;
      if (title) jobs.push({ title, company: co, location, url: jobUrl, board, jd_text: `${title} at ${co} — ${location}` });
    });
  } catch(e) {
    // HTML fallback for LinkedIn
    const tMatches = [...html.matchAll(/class="base-search-card__title"[^>]*>\s*([^<]+)/g)];
    const cMatches = [...html.matchAll(/class="base-search-card__subtitle"[^>]*>\s*([^<]+)/g)];
    const lMatches = [...html.matchAll(/class="job-search-card__location"[^>]*>\s*([^<]+)/g)];
    const uMatches = [...html.matchAll(/href="(https:\/\/www\.linkedin\.com\/jobs\/view\/[^"?]+)/g)];
    tMatches.slice(0, 15).forEach((m, i) => {
      const title = m[1].trim();
      const co = cMatches[i]?.[1]?.trim() || company;
      const location = lMatches[i]?.[1]?.trim() || 'India';
      const url = uMatches[i]?.[1] || sourceUrl;
      if (title) jobs.push({ title, company: co, location, url, board, jd_text: `${title} at ${co} — ${location}` });
    });
  }
}

// ── Naukri HTML ────────────────────────────────────────────
else if (board === 'Naukri') {
  const tMatches = [...html.matchAll(/class="title[^"]*"[^>]*>\s*<[^>]+>\s*([^<]+)/g)];
  const cMatches = [...html.matchAll(/class="comp-name[^"]*"[^>]*>\s*([^<]+)/g)];
  const lMatches = [...html.matchAll(/class="locWdth[^"]*"[^>]*>\s*([^<]+)/g)];
  const uMatches = [...html.matchAll(/href="(https:\/\/www\.naukri\.com\/job-listings[^"]+)"/g)];
  tMatches.slice(0, 15).forEach((m, i) => {
    const title = m[1].trim();
    const co = cMatches[i]?.[1]?.trim() || 'Unknown';
    const location = lMatches[i]?.[1]?.trim() || 'India';
    const url = uMatches[i]?.[1] || sourceUrl;
    if (title) jobs.push({ title, company: co, location, url, board, jd_text: `${title} at ${co} — ${location}` });
  });
}

// ── Barclays ───────────────────────────────────────────────
else if (board === 'Barclays') {
  const tMatches = [...html.matchAll(/class="job-title[^"]*"[^>]*>\s*<[^>]*>\s*([^<]+)/g)];
  const lMatches = [...html.matchAll(/class="job-location[^"]*"[^>]*>\s*([^<]+)/g)];
  const uMatches = [...html.matchAll(/href="(\/job\/[^"]+)"/g)];
  tMatches.slice(0, 10).forEach((m, i) => {
    const title = m[1].trim();
    const location = lMatches[i]?.[1]?.trim() || 'Pune';
    const url = uMatches[i] ? 'https://search.jobs.barclays' + uMatches[i][1] : sourceUrl;
    if (title) jobs.push({ title, company, location, url, board, jd_text: `${title} at ${company} — ${location}` });
  });
}

// ── Honeywell ──────────────────────────────────────────────
else if (board === 'Honeywell') {
  const tMatches = [...html.matchAll(/class="[^"]*job[^"]*title[^"]*"[^>]*>\s*([^<]+)/g)];
  const lMatches = [...html.matchAll(/class="[^"]*job[^"]*location[^"]*"[^>]*>\s*([^<]+)/g)];
  const uMatches = [...html.matchAll(/href="(\/us\/en\/job[^"]+)"/g)];
  tMatches.slice(0, 10).forEach((m, i) => {
    const title = m[1].trim();
    const location = lMatches[i]?.[1]?.trim() || 'India';
    const url = uMatches[i] ? 'https://careers.honeywell.com' + uMatches[i][1] : sourceUrl;
    if (title) jobs.push({ title, company, location, url, board, jd_text: `${title} at ${company} — ${location}` });
  });
}

// ── Siemens ────────────────────────────────────────────────
else if (board === 'Siemens') {
  const tMatches = [...html.matchAll(/"jobTitle":"([^"]+)"/g)];
  const lMatches = [...html.matchAll(/"jobLocation":"([^"]+)"/g)];
  const uMatches = [...html.matchAll(/"jobUrl":"([^"]+)"/g)];
  tMatches.slice(0, 10).forEach((m, i) => {
    const title = m[1];
    const location = lMatches[i]?.[1] || 'India';
    const url = uMatches[i]?.[1] || sourceUrl;
    if (title) jobs.push({ title, company, location, url, board, jd_text: `${title} at ${company} — ${location}` });
  });
  if (jobs.length === 0) {
    const tFallback = [...html.matchAll(/class="[^"]*job-name[^"]*"[^>]*>\s*([^<]+)/g)];
    tFallback.slice(0, 10).forEach((m, i) => {
      const title = m[1].trim();
      if (title) jobs.push({ title, company, location: 'Bangalore, India', url: sourceUrl, board, jd_text: `${title} at ${company} — Bangalore` });
    });
  }
}

// ── Goldman Sachs ──────────────────────────────────────────
else if (board === 'GoldmanSachs') {
  const tMatches = [...html.matchAll(/"title":"([^"]+)"/g)];
  const lMatches = [...html.matchAll(/"location":"([^"]+)"/g)];
  const uMatches = [...html.matchAll(/"url":"(\/careers\/[^"]+)"/g)];
  tMatches.slice(0, 10).forEach((m, i) => {
    const title = m[1];
    const location = lMatches[i]?.[1] || 'Bangalore';
    const url = uMatches[i] ? 'https://higher.gs.com' + uMatches[i][1] : sourceUrl;
    if (title) jobs.push({ title, company, location, url, board, jd_text: `${title} at ${company} — ${location}` });
  });
}

// ── EY GDS ────────────────────────────────────────────────
else if (board === 'EY_GDS') {
  const tMatches = [...html.matchAll(/class="[^"]*result-title[^"]*"[^>]*>\s*<[^>]+>\s*([^<]+)/g)];
  const lMatches = [...html.matchAll(/class="[^"]*result-location[^"]*"[^>]*>\s*([^<]+)/g)];
  tMatches.slice(0, 10).forEach((m, i) => {
    const title = m[1].trim();
    const location = lMatches[i]?.[1]?.trim() || 'India';
    if (title) jobs.push({ title, company, location, url: sourceUrl, board, jd_text: `${title} at ${company} — ${location}` });
  });
}

// ── Deloitte ───────────────────────────────────────────────
else if (board === 'Deloitte') {
  const tMatches = [...html.matchAll(/class="[^"]*job[^"]*title[^"]*"[^>]*>\s*([^<]+)/g)];
  const lMatches = [...html.matchAll(/class="[^"]*job[^"]*location[^"]*"[^>]*>\s*([^<]+)/g)];
  const uMatches = [...html.matchAll(/href="(\/careers\/[^"]+)"/g)];
  tMatches.slice(0, 10).forEach((m, i) => {
    const title = m[1].trim();
    const location = lMatches[i]?.[1]?.trim() || 'India';
    const url = uMatches[i] ? 'https://apply.deloitte.com' + uMatches[i][1] : sourceUrl;
    if (title) jobs.push({ title, company, location, url, board, jd_text: `${title} at ${company} — ${location}` });
  });
}

// ── Bosch ──────────────────────────────────────────────────
else if (board === 'Bosch') {
  const tMatches = [...html.matchAll(/class="[^"]*job-title[^"]*"[^>]*>\s*([^<]+)/g)];
  const lMatches = [...html.matchAll(/class="[^"]*location[^"]*"[^>]*>\s*([^<]+)/g)];
  tMatches.slice(0, 10).forEach((m, i) => {
    const title = m[1].trim();
    const location = lMatches[i]?.[1]?.trim() || 'Bangalore, India';
    if (title) jobs.push({ title, company, location, url: sourceUrl, board, jd_text: `${title} at ${company} — ${location}` });
  });
}

// ── Generic HTML fallback for all other boards ─────────────
// Catches: Shell, Cummins, VWITS, Eaton, HSBC, BP, Maersk,
// Mercedes, Unilever, Cargill, Telstra, Amex, Nokia,
// AstraZeneca, JPMorgan, Novartis, StanChart, 3M, Fidelity, DP World
else {
  // Try JSON title extraction first
  const jsonTitles = [...html.matchAll(/"(?:jobTitle|title|position|positionTitle|requisitionTitle)":"([^"]{5,120})"/g)];
  const jsonLocations = [...html.matchAll(/"(?:location|jobLocation|city|workLocation)":"([^"]{2,80})"/g)];
  const jsonUrls = [...html.matchAll(/"(?:url|applyUrl|jobUrl|link)":"(https?:\/\/[^"]+)"/g)];

  if (jsonTitles.length > 0) {
    jsonTitles.slice(0, 10).forEach((m, i) => {
      const title = m[1];
      const location = jsonLocations[i]?.[1] || 'India';
      const url = jsonUrls[i]?.[1] || sourceUrl;
      if (title) jobs.push({ title, company, location, url, board, jd_text: `${title} at ${company} — ${location}` });
    });
  } else {
    // Pure HTML fallback — common heading patterns across career sites
    const patterns = [
      /class="[^"]*(?:job-?title|position-?title|vacancy-?title|role-?title)[^"]*"[^>]*>\s*(?:<[^>]+>)?\s*([^<]{5,120})/g,
      /<h[123][^>]*class="[^"]*job[^"]*"[^>]*>\s*([^<]{5,120})/g,
      /<a[^>]+class="[^"]*(?:job|position|role)[^"]*"[^>]*>\s*([^<]{5,120})/g
    ];
    for (const pattern of patterns) {
      const matches = [...html.matchAll(pattern)];
      if (matches.length > 0) {
        matches.slice(0, 10).forEach(m => {
          const title = m[1].replace(/&amp;/g, '&').replace(/&#039;/g, "'").trim();
          if (title && title.length > 4) {
            jobs.push({ title, company, location: 'India', url: sourceUrl, board, jd_text: `${title} at ${company} — India` });
          }
        });
        break;
      }
    }
  }
}

// Skip marker if nothing found
if (jobs.length === 0) {
  return [{ json: { _skip: true, reason: `No jobs parsed from ${board}`, board, label, sourceUrl, scraped_at: scrapedAt } }];
}

return jobs.map(j => ({ json: { ...j, label, scraped_at: scrapedAt } }));

// ── 6-FAMILY KEYWORD RELEVANCE FILTER ─────────────────────
// Family 1: SIAM / Service Integration
// Family 2: IT Change Manager / Change Analyst
// Family 3: IT Service Delivery Manager
// Family 4: IT Operations Manager
// Family 5: Workforce / Capacity Planning
// Family 6: ServiceNow Specialist / Consultant

const item = $input.first().json;
const title = (item.title || '').toLowerCase();
const jd = (item.jd_text || '').toLowerCase();
const combined = title + ' ' + jd;

const FAMILIES = {
  'SIAM': ['siam', 'service integration', 'service integrat', 'multi-vendor governance', 'multi vendor governance', 'service integration manager'],
  'Change': ['change manager', 'change analyst', 'change management', 'change advisory', 'cab chair', 'itil change', 'change governance', 'it change'],
  'SDM': ['service delivery manager', 'service delivery lead', 'sdm', 'it service delivery', 'managed services delivery', 'service level manager'],
  'IT_Ops': ['it operations manager', 'it operations lead', 'it ops manager', 'infrastructure manager', 'it service manager', 'itsm manager', 'it service management', 'itsm lead', 'itsm governance', 'service manager'],
  'Workforce': ['workforce planning', 'capacity planning', 'resource manager', 'workforce manager', 'staffing manager', 'resource planning', 'workforce strategy', 'rebadging', 'pyramid optimis'],
  'ServiceNow': ['servicenow', 'service now', 'snow consultant', 'snow specialist', 'servicenow itsm', 'servicenow developer', 'servicenow admin', 'servicenow architect', 'now platform']
};

const matched_families = [];
const matched_keywords = [];

for (const [family, keywords] of Object.entries(FAMILIES)) {
  for (const kw of keywords) {
    if (combined.includes(kw)) {
      if (!matched_families.includes(family)) matched_families.push(family);
      if (!matched_keywords.includes(kw)) matched_keywords.push(kw);
    }
  }
}

// Exclude clearly irrelevant roles that may slip through generic scrapes
const EXCLUSIONS = ['software engineer', 'data scientist', 'machine learning engineer', 'data analyst', 'frontend developer', 'backend developer', 'devops engineer', 'qa engineer', 'test engineer', 'accountant', 'finance analyst', 'recruiter', 'hr business partner', 'graphic designer', 'legal counsel', 'sales executive', 'marketing manager'];
const excluded = EXCLUSIONS.some(ex => title.includes(ex));

if (matched_families.length === 0 || excluded) {
  return [{ json: { ...item, _relevant: false, matched_families: [], matched_keywords: [] } }];
}

return [{ json: { ...item, _relevant: true, matched_families, matched_keywords } }];

const raw = $input.first().json.response || $input.first().json.text || '';
const cleaned = raw.replace(/```json|```/g, '').trim();
const upstream = $('Code — 6-Family Keyword Filter').item.json;
try {
  const parsed = JSON.parse(cleaned);
  return [{ json: { ...upstream, jd_parsed: parsed } }];
} catch(e) {
  return [{ json: { ...upstream, jd_parsed: {}, parse_error: true, raw_ollama: raw } }];
}

const resp = $input.first().json;
const raw = resp.content?.[0]?.text || resp.text || '';
const cleaned = raw.replace(/```json|```/g, '').trim();
const upstream = $('Code — Parse Ollama JSON').item.json;
try {
  const parsed = JSON.parse(cleaned);
  return [{ json: { ...upstream, ...parsed } }];
} catch(e) {
  return [{ json: { ...upstream, parse_error: true, raw_score: raw, score: 0, match_strengths: [], skill_gaps: [], priority: 'low', apply_recommended: false, role_family: 'unknown' } }];
}

const resp = $input.first().json;
const raw = resp.content?.[0]?.text || resp.text || '';
const cleaned = raw.replace(/```json|```/g, '').trim();
const upstream = $('Code — Parse Score JSON').item.json;
try {
  const parsed = JSON.parse(cleaned);
  return [{ json: { ...upstream, ...parsed } }];
} catch(e) {
  return [{ json: { ...upstream, parse_error: true, resume_markdown: raw, cover_summary: '', gap_analysis: [], ats_keywords_used: [] } }];
}
